n.h6("          CREATE TABLE settings(\n            key TEXT PRIMARY KEY,\n            value TEXT\n          )\n          ")
n.h6("          CREATE TABLE bank_accounts(\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            preferred_name TEXT,\n            bank_name TEXT,\n            aspsp_country TEXT,\n            iban TEXT,\n            owner_name TEXT,\n            requisition_id TEXT,\n            account_id TEXT, -- GoCardless specific account ID\n            include_in_import INTEGER DEFAULT 1,\n            requisition_expiry TEXT, -- Store as ISO8601 String\n            agreement_id TEXT, -- Store the EUA ID\n            aisp TEXT,\n            application_id TEXT,\n            session_id TEXT,\n            balance_fetch_frequency TEXT,\n            -- No `balance` and no `last_balance_fetch_date` here on purpose:\n            -- both live in balance_snapshots now (v4). `balance` duplicated the\n            -- newest snapshot and the two drifted apart, which charted accounts\n            -- as falling to zero; `last_balance_fetch_date` is the poll clock and\n            -- is now MAX(created_at). See the doc comments on\n            -- dbColumnBankAccountBalance and\n            -- dbColumnBankAccountLastBalanceFetchDate.\n            account_type TEXT DEFAULT 'manual',\n            linked_account_id INTEGER,\n            currency_rate_source TEXT,\n            bank_fee_fixed REAL,\n            bank_fee_percentage REAL,\n            apple_wallet_card_name TEXT,\n            meal_voucher_cat_income TEXT,\n            meal_voucher_cat_expense TEXT,\n            asset_class TEXT,\n            include_in_net_worth INTEGER DEFAULT 1,\n            net_worth_history_mode TEXT DEFAULT 'auto',\n            net_worth_transactions_from TEXT\n          )\n          ")
n.h6("CREATE TABLE categories (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            name TEXT NOT NULL,\n            parent_name TEXT,\n            icon_name TEXT,\n            color_hex TEXT,\n            is_income INTEGER NOT NULL DEFAULT 0,\n            exclude_by_default INTEGER NOT NULL DEFAULT 0,\n            is_eenmalig INTEGER NOT NULL DEFAULT 0,\n            is_archived INTEGER DEFAULT 0,\n            is_salary_from TEXT\n          )")
n.h6("          CREATE TABLE category_context_usage (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            category_id INTEGER NOT NULL,\n            context TEXT NOT NULL,\n            last_used_date TEXT,\n            user_excluded INTEGER DEFAULT 0,\n            UNIQUE(category_id, context),\n            FOREIGN KEY(category_id) REFERENCES categories(id)\n          )\n        ")
n.h6("          CREATE INDEX idx_category_context_suggested\n            ON category_context_usage(context, user_excluded, last_used_date DESC)\n        ")
n.h6("          CREATE TABLE inflation_indices_country (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            country_code TEXT NOT NULL,\n            year INTEGER NOT NULL,\n            consumer_index REAL,\n            UNIQUE(country_code, year)\n          )\n        ")
n.h6("          CREATE TABLE common_transactions (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            tegenpartij TEXT NOT NULL UNIQUE,\n            niet_geindex_bedrag REAL,\n            categorie TEXT,\n            extra_info TEXT,\n            indexeren INTEGER NOT NULL DEFAULT 0,\n            availability_scope TEXT\n          )\n        ")
n.h6("          CREATE TABLE trip_participants (\n            trip_name TEXT NOT NULL,\n            participant_name TEXT NOT NULL,\n            me INTEGER DEFAULT 0,\n            PRIMARY KEY (trip_name, participant_name))\n        ")
n.h6("          CREATE TABLE trip_summary_data (\n            trip_name TEXT PRIMARY KEY NOT NULL,\n            earliest_consumed_date TEXT,\n            latest_consumed_date TEXT,\n            duration_days INTEGER,\n            grand_total_cost REAL,\n            category_costs TEXT,\n            indexed_grand_total_cost REAL,\n            indexed_category_costs TEXT,\n            country_costs TEXT,\n            indexed_country_costs TEXT,\n            custom_start_date TEXT,\n            custom_end_date TEXT,\n            trip_description TEXT\n          )\n        ")
n.h6("    CREATE TABLE fire_rules (\n      id                INTEGER PRIMARY KEY AUTOINCREMENT,\n      rule_type         TEXT NOT NULL,\n      category_id       INTEGER,\n      person            TEXT,\n      description       TEXT,\n      amount            REAL,\n      amount_unit       TEXT,\n      direction         TEXT,\n      vanaf_type        TEXT NOT NULL,\n      vanaf_value       TEXT NOT NULL,\n      tot_type          TEXT,\n      tot_value         TEXT,\n      is_pension_rule   INTEGER NOT NULL DEFAULT 0\n    )\n  ")
n.h6("          CREATE TABLE countries (\n            id TEXT PRIMARY KEY,\n            name TEXT NOT NULL,\n            currency_code TEXT NOT NULL,\n            iso_alpha2 TEXT,\n            currency_symbol TEXT\n          )\n        ")
n.h6("          CREATE TABLE exchange_rates (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            date TEXT NOT NULL,\n            base_currency TEXT NOT NULL,\n            target_currency TEXT NOT NULL,\n            rate REAL NOT NULL,\n            source TEXT NOT NULL,\n            fetched_at TEXT NOT NULL,\n            UNIQUE(date, base_currency, target_currency, source)\n          )\n        ")
n.h6("CREATE INDEX idx_exchange_rates_lookup ON exchange_rates(date, base_currency, target_currency, source)")
n.h6("          CREATE TABLE IF NOT EXISTS tags (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            name TEXT NOT NULL UNIQUE,\n            color_hex TEXT NOT NULL,\n            sort_order INTEGER DEFAULT 0\n          )\n        ")
